export type ImportTimingPhase = "opening" | "database" | "cards" | "media" | "saving";

export interface ImportTiming {
  totalMs: number;
  openingMs: number;
  databaseMs: number;
  cardsMs: number;
  mediaMs: number;
  savingMs: number;
}

const EMPTY_TIMING: ImportTiming = {
  totalMs: 0,
  openingMs: 0,
  databaseMs: 0,
  cardsMs: 0,
  mediaMs: 0,
  savingMs: 0,
};

export class ImportTimingTracker {
  private readonly startedAt: number;
  private lastAt: number;
  private phase: ImportTimingPhase | undefined;
  private timing: ImportTiming = { ...EMPTY_TIMING };

  constructor(private readonly now: () => number = () => performance.now()) {
    this.startedAt = now();
    this.lastAt = this.startedAt;
  }

  transition(nextPhase: ImportTimingPhase): void {
    this.capture();
    this.phase = nextPhase;
  }

  snapshot(): ImportTiming {
    const copy = { ...this.timing };
    const now = this.now();
    if (this.phase) copy[`${this.phase}Ms`] += Math.max(0, now - this.lastAt);
    copy.totalMs = Math.max(0, now - this.startedAt);
    return copy;
  }

  finish(): ImportTiming {
    this.capture();
    this.phase = undefined;
    return { ...this.timing, totalMs: Math.max(0, this.lastAt - this.startedAt) };
  }

  private capture(): void {
    const now = this.now();
    if (this.phase) this.timing[`${this.phase}Ms`] += Math.max(0, now - this.lastAt);
    this.lastAt = now;
    this.timing.totalMs = Math.max(0, now - this.startedAt);
  }
}

export function formatImportDuration(milliseconds: number): string {
  const seconds = Math.max(0, Math.round(milliseconds / 1000));
  const minutes = Math.floor(seconds / 60);
  return minutes ? `${minutes}分${seconds % 60}秒` : `${seconds}秒`;
}

export function formatImportTiming(timing: ImportTiming): string {
  const parts: string[] = [];
  const labels: Array<[keyof ImportTiming, string]> = [
    ["openingMs", "目次"],
    ["databaseMs", "DB"],
    ["cardsMs", "カード"],
    ["mediaMs", "画像・音声"],
    ["savingMs", "仕上げ"],
  ];
  for (const [key, label] of labels) {
    if (timing[key] >= 500) parts.push(`${label} ${formatImportDuration(timing[key])}`);
  }
  return parts.length ? `合計 ${formatImportDuration(timing.totalMs)}（${parts.join("・")}）` : `合計 ${formatImportDuration(timing.totalMs)}`;
}
