import type { DeckOptionPreset, Grade, ProgressRecord, ReviewInterval, SchedulerCardState } from "./types";
import { dueAtForInterval, nextStudyDayStart, studyDayStartAt } from "./scheduler";

export interface ScheduledAnswer {
  dueAt: number;
  interval: ReviewInterval;
  state: SchedulerCardState;
}

const cloneState = (state: SchedulerCardState): SchedulerCardState => ({ ...state });

function dayDueAt(days: number, reviewedAt: number, dayStartMinutes: number): number {
  const start = new Date(studyDayStartAt(reviewedAt, dayStartMinutes));
  start.setDate(start.getDate() + Math.max(1, Math.round(days)));
  return start.getTime();
}

function intervalForDueAt(dueAt: number, reviewedAt: number, dayStartMinutes: number): ReviewInterval {
  const nextDay = nextStudyDayStart(reviewedAt, dayStartMinutes);
  if (dueAt >= nextDay) {
    const days = Math.max(1, Math.round((dueAt - studyDayStartAt(reviewedAt, dayStartMinutes)) / 86_400_000));
    return { value: days, unit: "day" };
  }
  const minutes = Math.max(1, Math.round((dueAt - reviewedAt) / 60_000));
  if (minutes >= 60 && minutes % 60 === 0) return { value: minutes / 60, unit: "hour" };
  return { value: minutes, unit: "minute" };
}

function scheduledStep(step: ReviewInterval, state: SchedulerCardState, reviewedAt: number, dayStartMinutes: number): ScheduledAnswer {
  const dueAt = dueAtForInterval(step, reviewedAt, dayStartMinutes);
  return { dueAt, interval: intervalForDueAt(dueAt, reviewedAt, dayStartMinutes), state };
}

function freshState(options: DeckOptionPreset): SchedulerCardState {
  return {
    phase: "learning",
    stepIndex: 0,
    intervalDays: 0,
    easeFactor: options.startingEase,
    lapses: 0,
    leech: false,
    suspended: false,
  };
}

export function schedulerStateForProgress(progress: ProgressRecord | undefined, options: DeckOptionPreset): SchedulerCardState | undefined {
  if (!progress) return undefined;
  if (progress.schedulerState) return cloneState(progress.schedulerState);
  const elapsedDays = progress.dueAt
    ? Math.max(1, Math.round((progress.dueAt - progress.lastReviewedAt) / 86_400_000))
    : options.graduatingIntervalDays;
  return {
    phase: "review",
    stepIndex: 0,
    intervalDays: elapsedDays,
    easeFactor: options.startingEase,
    lapses: 0,
    leech: false,
    suspended: false,
  };
}

function learningHardDelay(steps: readonly ReviewInterval[], index: number): ReviewInterval {
  const current = steps[index] ?? steps[0] ?? { value: 1, unit: "minute" };
  const next = steps[index + 1];
  if (!next) return current;
  const toMinutes = (step: ReviewInterval): number => step.value * (step.unit === "minute" ? 1 : step.unit === "hour" ? 60 : 1440);
  const minutes = Math.max(1, Math.round((toMinutes(current) + toMinutes(next)) / 2));
  if (minutes % 1440 === 0) return { value: minutes / 1440, unit: "day" };
  if (minutes % 60 === 0) return { value: minutes / 60, unit: "hour" };
  return { value: minutes, unit: "minute" };
}

function graduate(state: SchedulerCardState, days: number, reviewedAt: number, dayStartMinutes: number): ScheduledAnswer {
  const intervalDays = Math.max(1, Math.round(days));
  const next = { ...state, phase: "review" as const, stepIndex: 0, intervalDays };
  return { dueAt: dayDueAt(intervalDays, reviewedAt, dayStartMinutes), interval: { value: intervalDays, unit: "day" }, state: next };
}

function scheduleLearning(
  state: SchedulerCardState,
  grade: Grade,
  options: DeckOptionPreset,
  reviewedAt: number,
  dayStartMinutes: number,
): ScheduledAnswer {
  const relearning = state.phase === "relearning";
  const steps = relearning ? options.relearningSteps : options.learningSteps;
  const fallbackInterval = relearning
    ? Math.max(options.minimumIntervalDays, state.intervalDays)
    : options.graduatingIntervalDays;
  if (!steps.length) return graduate(state, grade === "easy" ? options.easyIntervalDays : fallbackInterval, reviewedAt, dayStartMinutes);
  if (grade === "again") {
    const next = { ...state, stepIndex: 0 };
    return scheduledStep(steps[0], next, reviewedAt, dayStartMinutes);
  }
  if (grade === "hard") {
    const index = Math.min(state.stepIndex, steps.length - 1);
    return scheduledStep(learningHardDelay(steps, index), { ...state, stepIndex: index }, reviewedAt, dayStartMinutes);
  }
  if (grade === "easy") return graduate(state, relearning ? Math.max(fallbackInterval, options.easyIntervalDays) : options.easyIntervalDays, reviewedAt, dayStartMinutes);
  const nextIndex = state.stepIndex + 1;
  if (nextIndex < steps.length) return scheduledStep(steps[nextIndex], { ...state, stepIndex: nextIndex }, reviewedAt, dayStartMinutes);
  return graduate(state, fallbackInterval, reviewedAt, dayStartMinutes);
}

function constrainedInterval(raw: number, previous: number, options: DeckOptionPreset): number {
  return Math.min(options.maximumIntervalDays, Math.max(previous + 1, 1, Math.round(raw)));
}

function lateDays(progress: ProgressRecord | undefined, reviewedAt: number): number {
  if (!progress?.dueAt || progress.dueAt >= reviewedAt) return 0;
  return Math.max(0, Math.floor((reviewedAt - progress.dueAt) / 86_400_000));
}

function scheduleReview(
  state: SchedulerCardState,
  progress: ProgressRecord | undefined,
  grade: Grade,
  options: DeckOptionPreset,
  reviewedAt: number,
  dayStartMinutes: number,
): ScheduledAnswer {
  const previous = Math.max(1, state.intervalDays || options.graduatingIntervalDays);
  const overdue = lateDays(progress, reviewedAt);
  if (grade === "again") {
    const lapseCount = (state.lapses ?? 0) + 1;
    const intervalDays = Math.max(options.minimumIntervalDays, Math.round(previous * options.newInterval));
    const leech = options.leechThreshold > 0 && lapseCount >= options.leechThreshold;
    const next: SchedulerCardState = {
      ...state,
      phase: options.relearningSteps.length ? "relearning" : "review",
      stepIndex: 0,
      intervalDays,
      easeFactor: Math.max(1.3, state.easeFactor - 0.2),
      lapses: lapseCount,
      leech: state.leech || leech,
      suspended: state.suspended || (leech && options.leechAction === "suspend"),
    };
    if (options.relearningSteps.length) return scheduledStep(options.relearningSteps[0], next, reviewedAt, dayStartMinutes);
    return graduate(next, intervalDays, reviewedAt, dayStartMinutes);
  }
  const hardDays = constrainedInterval(previous * options.hardInterval * options.intervalModifier, previous, options);
  const goodDays = Math.max(hardDays + 1, constrainedInterval((previous + overdue / 2) * state.easeFactor * options.intervalModifier, previous, options));
  const easyDays = Math.max(goodDays + 1, constrainedInterval((previous + overdue) * state.easeFactor * options.easyBonus * options.intervalModifier, previous, options));
  const intervalDays = grade === "hard" ? hardDays : grade === "easy" ? easyDays : goodDays;
  const easeFactor = grade === "hard"
    ? Math.max(1.3, state.easeFactor - 0.15)
    : grade === "easy" ? Math.min(5, state.easeFactor + 0.15) : state.easeFactor;
  return graduate({ ...state, easeFactor }, intervalDays, reviewedAt, dayStartMinutes);
}

export function scheduleSm2Answer(
  progress: ProgressRecord | undefined,
  grade: Grade,
  options: DeckOptionPreset,
  reviewedAt: number,
  dayStartMinutes: number,
): ScheduledAnswer {
  const state = schedulerStateForProgress(progress, options) ?? freshState(options);
  return state.phase === "review"
    ? scheduleReview(state, progress, grade, options, reviewedAt, dayStartMinutes)
    : scheduleLearning(state, grade, options, reviewedAt, dayStartMinutes);
}

export function previewSm2Answers(
  progress: ProgressRecord | undefined,
  options: DeckOptionPreset,
  reviewedAt: number,
  dayStartMinutes: number,
): Record<Grade, ScheduledAnswer> {
  return {
    again: scheduleSm2Answer(progress, "again", options, reviewedAt, dayStartMinutes),
    hard: scheduleSm2Answer(progress, "hard", options, reviewedAt, dayStartMinutes),
    good: scheduleSm2Answer(progress, "good", options, reviewedAt, dayStartMinutes),
    easy: scheduleSm2Answer(progress, "easy", options, reviewedAt, dayStartMinutes),
  };
}
