import type { TodayHiddenRecord } from "./types";
import { nextStudyDayStart } from "./scheduler";

export function nextLocalMidnight(now = Date.now()): number {
  return nextStudyDayStart(now, 0);
}

export function activeTodayHidden(records: TodayHiddenRecord[] | undefined, now = Date.now()): TodayHiddenRecord[] {
  return (records ?? []).filter((record) => record.hiddenUntil > now);
}

export function todayHiddenCardIds(
  records: TodayHiddenRecord[] | undefined,
  deckId: string,
  now = Date.now(),
): Set<string> {
  return new Set(activeTodayHidden(records, now)
    .filter((record) => record.deckId === deckId)
    .map((record) => record.cardId));
}

export function hideCardUntilTomorrow(
  records: TodayHiddenRecord[] | undefined,
  deckId: string,
  cardId: string,
  now = Date.now(),
  dayStartMinutes = 0,
): TodayHiddenRecord[] {
  const active = activeTodayHidden(records, now)
    .filter((record) => record.deckId !== deckId || record.cardId !== cardId);
  active.push({ deckId, cardId, hiddenUntil: nextStudyDayStart(now, dayStartMinutes) });
  return active;
}

export function releaseTodayHiddenCards(
  records: TodayHiddenRecord[] | undefined,
  deckId: string,
  cardIds: ReadonlySet<string>,
  now = Date.now(),
): TodayHiddenRecord[] {
  return activeTodayHidden(records, now)
    .filter((record) => record.deckId !== deckId || !cardIds.has(record.cardId));
}
